static long test_device_ioctl(struct file *file, unsigned int cmd, unsigned long arg) {
    switch (cmd) {
        case TEST_DEVICE_RESET:
            return test_device_reset();
        case TEST_DEVICE_STATUS:
            return test_device_get_status(arg);
        default:
            return -ENOTTY;
    }
}
